import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import { Row, Col, Form, notification, Divider, Alert } from 'antd'
import IntlMessages from '../../../../../components/utility/intlMessages'
import queryString from 'query-string'
import policyAction from '../../../../../redux/policy/actions'
import CircularLoader from '../../../../../components/CircularLoader'
import { getFormItems } from '../../../../../components/utility/formItems'
import validator from '../../../../../helpers/validator'
import { RukitaVehicleContainerStyle } from './index.style'
import FileUploadSection from '../FileUploadSection'
import FileUploadInteriorSection from '../FileUploadInteriorSection'
import EndorseWelcome from '../ThankYouComponent'
import { ERROR_STRINGS } from '../../../../../constants/lang'
import _, { get } from 'lodash'

const { resetReduxPolicy, tokenizedDetailEndorsement, authorisedEndorsement } = policyAction

class RukitaVehileEndorsementContainer extends Component {
  constructor (props) {
    super(props)
    this.state = {
      imageUrls: {
        top: '',
        bottom: '',
        left: '',
        right: ''
      },
      interiorImageUrls: {
        roof: '',
        interior: '',
        plateNumber: '',
        engineNumber: '',
        stnkFront: '',
        stnkBack: ''
      },
      buttonDisabled: true,
      internalID: '',
      token: ''
    }
  }
  static propTypes = {
    id: PropTypes.string
  };

  componentDidMount () {
    const { id } = this.props
    const internalId = get(id, 'match.params.id')
    const tokenObject = get(id, 'location.search', '')
    if (tokenObject) {
      const token = get(queryString.parse(tokenObject), 'token', '')
      if (token && internalId) {
        this.setState({
          internalId: internalId,
          token: token
        })
        this.props.tokenizedDetailEndorsement({
          query: {
            id: internalId,
            token: token
          }
        })
      }
    }
  }

  componentWillReceiveProps (nextProps) {
    const {
      policyEndorsementError,
      policyEndorsement,
      policyEndorsementMessage
    } = nextProps
    if (
      policyEndorsementMessage !== '' &&
      policyEndorsementMessage !== 'success'
    ) {
      const errorData = _.uniq(get(policyEndorsement, 'error', ''))
      const errorDataV2 = get(policyEndorsement, 'errors_v2', '')

      if (!policyEndorsementError && errorData && errorData !== 'success') {
        if (Array.isArray(errorData)) {
          errorData.forEach((item) => {
            const key = get(item, 'key', '')
            if (key === 'photo.interior') {
              notification.error({
                message: 'Please Upload Interior Image'
              })
              this.props.resetReduxPolicy(['authorizedEndorsementDataMessage'])
            } else if (key) {
              let message = item.err
              if (errorDataV2) {
                message = get(errorDataV2, 'message', '')
                message = message ? get(message, 'en', item.err) : item.err
              }
              this.props.form.setFields({
                [item.key]: {
                  value: item.val,
                  errors: [new Error(message)]
                }
              })
            } else {
              notification['error']({
                message: this.intlText({ id: 'Error' }),
                description: this.intlText({ id: item.err })
              })
            }
          })
          this.props.resetReduxPolicy(['authorizedEndorsementDataMessage'])
        } else {
          notification['error']({
            message: this.intlText({ id: 'Error' }),
            description: this.intlText({ id: errorData })
          })
          this.props.resetReduxPolicy(['authorizedEndorsementDataMessage'])
        }
      } else if (policyEndorsementMessage && policyEndorsementError) {
        notification.error({
          message: policyEndorsementMessage
        })
        this.props.resetReduxPolicy(['authorizedEndorsementDataMessage'])
      }
    }
  }

  leftSection = () => {
    return (
      <React.Fragment>
        {getFormItems.call(this, {
          formName: 'brand',
          type: 'alphanumeric',
          label: 'Brand',
          placeHolder: 'Select Brand',
          required: true,
          validator: validator.validateName
        })}
        {getFormItems.call(this, {
          formName: 'type',
          type: 'alphanumeric',
          label: 'Model',
          placeHolder: 'Select Model',
          required: true,
          validator: validator.validateGadgetModelName
        })}
        {getFormItems.call(this, {
          formName: 'color',
          type: 'alphanumeric',
          label: 'Color',
          placeHolder: 'Select Color',
          required: true,
          validator: validator.validateColor
        })}
        {getFormItems.call(this, {
          formName: 'year',
          type: 'alphanumeric',
          label: 'Year',
          placeHolder: 'Select Year',
          required: true,
          validator: validator.validateYear
        })}
      </React.Fragment>
    )
  };

  rightSection = () => {
    return (
      <React.Fragment>
        {getFormItems.call(this, {
          formName: 'plate_number',
          type: 'alphanumeric',
          label: 'Plate Number',
          placeHolder: 'e.g. B1234XYZ',
          required: true,
          validator: validator.checkPlateNumberAll
        })}
        {getFormItems.call(this, {
          formName: 'chassis_number',
          type: 'alphanumeric',
          label: 'Chassis Number',
          placeHolder: 'Input Chasis Number',
          required: true,
          validator: validator.validateChasisNumber
        })}
        {getFormItems.call(this, {
          formName: 'engine_number',
          type: 'alphanumeric',
          label: 'Engine Number',
          placeHolder: 'Input Engine Number',
          required: true,
          validator: validator.validateAllEngineNumber
        })}
      </React.Fragment>
    )
  };

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  };

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  handleFormSubmit = async (e) => {
    e.preventDefault()
    const {
      buttonDisabled,
      imageUrls,
      interiorImageUrls,
      internalId,
      token
    } = this.state
    const { top, bottom, left, right } = imageUrls
    const {
      roof,
      interior,
      plateNumber,
      engineNumber,
      stnkFront,
      stnkBack
    } = interiorImageUrls

    const { form } = this.props

    const valid = await this.validateForm()
    if (!valid) {
      notification.error({
        message: 'Please Fill the Entries Properly'
      })
      return
    }

    if (buttonDisabled) {
      notification.warning({
        message: 'Please Upload All the Side Images'
      })
      return
    }

    if (!stnkBack || !stnkFront) {
      notification.warning({
        message: 'Please Upload Stnk Images'
      })
      return
    }

    if (!engineNumber || !plateNumber) {
      notification.warning({
        message: 'Please Upload Plate Number and Chasis Images'
      })
      return
    }

    const formBody = form.getFieldsValue()
    if (formBody.chassis_number === formBody.engine_number) {
      notification.warning({
        message: 'Duplicate Values',
        description: 'Chasis Number and Engine number having same value'
      })
    } else {
      const body = {
        ...formBody,
        photo: {
          left: left,
          right: right,
          front: top,
          back: bottom,
          roof: roof,
          interior: interior,
          plate_number: plateNumber,
          machine_number: engineNumber
        },
        stnk_photo: {
          back: stnkBack,
          front: stnkFront
        }
      }

      this.props.authorisedEndorsement({
        query: {
          internal_id: internalId,
          token: token
        },
        body: body
      })
    }
  };

  getUploadUrls = (data) => {
    const { imageUrls } = this.state
    const imageObject = Object.keys(data)
    const comparingArray = Object.keys(imageUrls)
    if (_.isEqual(imageObject.sort(), comparingArray.sort())) {
      this.setState({
        imageUrls: data,
        buttonDisabled: false
      })
    }
  };

  getUploadsInteriorUrls = (data) => {
    this.setState({
      interiorImageUrls: data
    })
  };

  showErrorMessage = () => {
    return (
      <Alert
        message={<IntlMessages id={ERROR_STRINGS.error} />}
        description={<IntlMessages id={ERROR_STRINGS.serverError} />}
        type='error'
      />
    )
  };

  render () {
    const {
      getPolicyEndorsementDetailResult,
      policyEndorsementDetailLoading,
      policyEndorsementDetailError,
      policyEndorsementLoading,
      policyEndorsementMessage
    } = this.props
    const isSuccessFulEndorse =
      policyEndorsementMessage === 'success' ||
      get(getPolicyEndorsementDetailResult, 'EndorsementStatus') === 'SUCCESS'

    return (
      <React.Fragment>
        {isSuccessFulEndorse ? (
          <EndorseWelcome />
        ) : policyEndorsementDetailError ? (
          this.showErrorMessage()
        ) : (
          <RukitaVehicleContainerStyle>
            <CircularLoader
              isSpining={
                policyEndorsementDetailLoading || policyEndorsementLoading
              }
            >
              <Row type='flex' align='middle'>
                <Col sm={4} md={8}>
                  <h3 className='heading'>
                    <b>Fill Your Vehicle Detail</b>
                  </h3>
                </Col>

                <Col>
                  <p>
                    Please complete the form below to continue the motor vehicle
                    insurance activation process
                  </p>
                </Col>
              </Row>

              <Divider />
              <Form onSubmit={this.handleFormSubmit}>
                <h2>Vehile Details</h2>
                <div className='form-wrapper'>
                  <div className='row-item mobile-view-flex'>
                    {this.leftSection()}
                  </div>

                  <div className='row-item mobile-view-flex'>
                    {this.rightSection()}
                  </div>
                </div>

                <h2>Vehicle Photo</h2>

                <div className='form-wrapper'>
                  <div className='row-grid-upload mobile-view-flex'>
                    <FileUploadSection getUploadUrls={this.getUploadUrls} />
                  </div>

                  <div className='row-grid-interior-upload mobile-view-flex'>
                    <FileUploadInteriorSection
                      getUploadUrls={this.getUploadsInteriorUrls}
                    />
                  </div>
                </div>

                <div className='form-submit'>
                  <button type='submit'>
                    <strong>Submit</strong>
                  </button>
                </div>
              </Form>
            </CircularLoader>
          </RukitaVehicleContainerStyle>
        )}
      </React.Fragment>
    )
  }
}

const RukitaVehicleEndorsementContainerWrapped = Form.create()(
  RukitaVehileEndorsementContainer
)

export default connect(
  (state) => ({
    getPolicyEndorsementDetailResult: state.Policy.tokenisedEndorsementDetail,
    policyEndorsementDetailLoading: state.Loading.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsementDetailError: state.Error.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsement: state.Policy.authorizedEndorsementData,
    policyEndorsementMessage: state.Policy.authorizedEndorsementDataMessage,
    policyEndorsementLoading: state.Loading.AUTHORIZED_ENDORSEMENT,
    policyEndorsementError: state.Error.AUTHORIZED_ENDORSEMENT
  }),
  {
    authorisedEndorsement,
    tokenizedDetailEndorsement,
    resetReduxPolicy
  }
)(injectIntl(RukitaVehicleEndorsementContainerWrapped))
