import React, { Component } from 'react'
import PropTypes from 'prop-types'
import _ from 'lodash/object'
import FileUpload from '../FileUpload'
import { ENDORSE_LANG } from '../../../constants'

class FileUploadSection extends Component {
  static propTypes = {
    getUploadUrls: PropTypes.func,
    internalId: PropTypes.string
  };

  constructor (props) {
    super(props)
    this.state = {
      imageUrls: {},
      filesSections: [
        {
          heading: 'Roof (Top View)',
          tile: 'roof',
          title: 'Front Side',
          guide: false
        },
        {
          heading: 'Interior (Dashboard)',
          tile: 'interior',
          title: ENDORSE_LANG.uploadRearSide,
          guide: false
        },
        {
          heading: 'Plate Number',
          tile: 'plateNumber',
          guide: false,
          title: ENDORSE_LANG.uploadLeftSide
        },
        {
          heading: 'Chasis / Engine Number',
          tile: 'engineNumber',
          title: ENDORSE_LANG.uploadRightSide,
          guide: true
        },
        {
          heading: 'STNK Front Side',
          tile: 'stnkFront',
          title: ENDORSE_LANG.uploadRightSide,
          guide: true
        },
        {
          heading: 'STNK Back Side (Tax)',
          tile: 'stnkBack',
          title: ENDORSE_LANG.uploadRightSide,
          guide: true
        }
      ]
    }
  }

  getUploadImageUrl = (url, active) => {
    this.setState(
      (prevState) => ({
        imageUrls: {
          ...prevState.imageUrls,
          [active]: url
        }
      }),
      () => {
        const isAllFields = !(Object.keys(this.state.imageUrls).length < 4)
        this.props.getUploadUrls(
          this.state.imageUrls,
          isAllFields,
          this.props.internalId
        )
      }
    )
  };

  render () {
    const { imageUrls, filesSections } = this.state
    return (
      <React.Fragment>
        {filesSections.map((item) => (
          <div className='grid-container-item'>
            <FileUpload
              active={item.tile}
              imgUrl={_.get(imageUrls, item.tile)}
              title={item.title}
              getUploadImageUrl={this.getUploadImageUrl}
              heading={item.heading}
              guide={item.guide}
            />
          </div>
        ))}
      </React.Fragment>
    )
  }
}

export default FileUploadSection
