import React, { Component } from 'react'
import PropTypes from 'prop-types'
import _ from 'lodash/object'
import FileUpload from '../FileUpload'
import { ENDORSE_LANG } from '../../../constants'

class FileUploadSection extends Component {
  static propTypes = {
    getUploadUrls: PropTypes.func,
    internalId: PropTypes.string
  }

  constructor (props) {
    super(props)
    this.state = {
      imageUrls: {},
      filesSections: [
        {
          heading: 'Front Side',
          tile: 'top',
          title: 'Front Side'
        },
        {
          heading: 'Back Side',
          tile: 'bottom',
          title: ENDORSE_LANG.uploadRearSide
        },
        {
          heading: 'Left Side',
          tile: 'left',
          title: ENDORSE_LANG.uploadLeftSide
        },
        {
          heading: 'Right Side',
          tile: 'right',
          title: ENDORSE_LANG.uploadRightSide
        }
      ]
    }
  }

  getUploadImageUrl = (url, active) => {
    this.setState((prevState) => ({
      imageUrls: {
        ...prevState.imageUrls,
        [active]: url
      }
    }), () => {
      const isAllFields = !(Object.keys(this.state.imageUrls).length < 4)
      this.props.getUploadUrls(this.state.imageUrls, isAllFields, this.props.internalId)
    })
  }

  render () {
    const { imageUrls, filesSections } = this.state
    return (
      <React.Fragment>
        {
          filesSections.map(item => (
            <div className='grid-container-item'>
              <FileUpload
                active={item.tile}
                imgUrl={_.get(imageUrls, item.tile)}
                title={item.title}
                getUploadImageUrl={this.getUploadImageUrl}
                heading={item.heading}
              />
            </div>
          ))
        }
      </React.Fragment>
    )
  }
}

export default FileUploadSection
